"""Plan H3 shots around static screen images; never submit GPU jobs."""
from pathlib import Path
import json,math
p=Path(__file__).resolve().parent
specs=json.loads((p/'scene_specs.json').read_text());audio={r['id']:r for r in json.loads((p/'audio_manifest.json').read_text())};dialogue={r['id']:r for r in json.loads((p.parent/'remotion/src/dialogue.json').read_text())}
shots=[]
for scene in specs:
 groups=[];group=[];seconds=0
 for idx in scene['lines']:
  row=audio[idx];duration=row['input_seconds']+dialogue[idx]['pauseFrames']/24
  if group and (len(group)>=3 or seconds+duration>14.8):groups.append(group);group=[];seconds=0
  group.append(idx);seconds+=duration
 if group:groups.append(group)
 for group in groups:
  secs=sum(audio[x]['input_seconds']+dialogue[x]['pauseFrames']/24 for x in group);frames=17*math.ceil((secs*24-5)/17)+5;assert frames<=362
  shot=dict(id=f'ch{len(shots)+1:02}',scene=scene['id'],lines=group,audio=[audio[x]['input'] for x in group],frames=frames,seconds=frames/24,mode='r2v',visual_reference=f"scenes/{scene['id']}.png",screen=scene.get('adopted_slide',scene['slide']),action=scene['action'],screen_render='H3; static throughout shot',status='prepared_not_generated')
  shots.append(shot)
(p/'chapter_plan.json').write_text(json.dumps(shots,ensure_ascii=False,indent=2)+'\n')
(p/'prompts').mkdir(exist_ok=True)
for shot in shots:
 text=f"Required attached input files:\n<Picture 1> = {shot['visual_reference']} — exact scene, static slide and composition.\n<Picture 2> = refs/sobaya_canonical.png — identity only, not its clothing, props or panel layout.\n<Picture 3> = refs/sobaya_face.jpg — mask identity.\n<Picture 4> = refs/product_original.webp — original product artwork only.\n"
 if shot['scene'] < 's08_reveal':text=text.replace('<Picture 4> = refs/product_original.webp — original product artwork only.\n','')
 for i,idx in enumerate(shot['lines'],1):text+=f"<Audio {i}> = {audio[idx]['input']} — completed Sobaya dialogue, use AS-IS.\n"
 text+='\nReal live keynote photographed with modern broadcast clarity, the same stage, costume, lighting and rigid white mask as Picture 1. Black turtleneck, blue jeans, neutral gray exposed skin including all hands. Do not remove or deform mask. No additional people onstage. Any people pictured in the projected slide are frozen pixels; they never move or become live characters. No CG/game look. The large physical screen must keep EXACTLY the static slide from Picture 1 for the entire shot: '+shot['screen']+' No animation, morphing, video footage or transitions inside screen. It is generated by H3 as part of the scene, not replaced in editing. Keep text and graphics legible and fixed.\n'
 if shot['scene'] < 's08_reveal':text+='Do not reveal the final printed T-shirt product or the combined name 窓際族Tシャツ yet. Only show the separately introduced symbols already in Picture 1. No physical printed product onstage.\n'
 text+='Performance: '+shot['action']+' Small natural gestures aligned with speech, brief glance toward the indicated slide then audience. Keep body clear of important slide content. Static broadcast camera or extremely slow small push-in; never crop out the slide.\n'
 for i,idx in enumerate(shot['lines'],1):text+=f"Sobaya (S1) says <d>[Japanese] {audio[idx]['text']}</d> to <Audio {i}>, in this order. "
 text+='Use the attached WAV performances AS-IS; do not invent voices, change words, repeat or add speech. Match speech with head and hand acting while the rigid mask mouth aperture stays fixed. Pause naturally between lines. No subtitles; these will be added in Remotion. Soundscape: quiet auditorium air, no competing speech. Music: none.\n'
 (p/'prompts'/f"{shot['id']}.txt").write_text(text)
print(len(shots),'shots',sum(r['seconds'] for r in shots),'seconds')
